SELECT op_action, operator_name, target_name, reason, extra_text, notify_text, created_at
FROM t_operation_log
WHERE biz_type = #{bizType}
  AND biz_id = #{bizId}
ORDER BY created_at DESC, id DESC
LIMIT 100
